referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const escape = (s) =>
    s
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  const walk = (n) => {
    if (typeof n === "string") return escape(n);
    if (!["p", "b", "i", "a", "div"].includes(n.tag)) return "";
    const href = n.attrs.href;
    const attr =
      n.tag === "a" &&
      typeof href === "string" &&
      (href.startsWith("https://") || href.startsWith("/"))
        ? ' href="' + escape(href) + '"'
        : "";
    return "<" + n.tag + attr + ">" + n.children.map(walk).join("") + "</" + n.tag + ">";
  };
  return walk(d);
}

